INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'security', 'n.', '/sɪˈkjʊərɪti/', '安全;安全感', 'Many users worry about their privacy and information security online.', '许多用户担心自己在网上的隐私和信息安全。', 'Improving Yourself', 1, 0, 'senior', 'wordlist', 'elective2', 'U2', 'information security', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'switch', 'v.', '/swɪtʃ/', '（用开关）改变;转换;切换', 'I switch off my phone before I start studying.', '开始学习前我会把手机关掉。', 'Improving Yourself', 2, 0, 'senior', 'wordlist', 'elective2', 'U2', 'switch off', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'switch on', 'phr.', '/swɪtʃ ɒn/', '（用开关）开;打开', 'After the detox, they were eager to switch on their devices again.', '脱瘾结束后，他们急着重新打开自己的设备。', 'Improving Yourself', 3, 0, 'senior', 'wordlist', 'elective2', 'U2', 'switch on the device', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'motivate', 'v.', '/ˈməʊtɪveɪt/', '激发;激励', 'A small reward can motivate students to keep a good habit.', '小小的奖励能激励学生坚持好习惯。', 'Improving Yourself', 4, 0, 'senior', 'wordlist', 'elective2', 'U2', 'motivate students', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'occupy', 'v.', '/ˈɒkjʊpaɪ/', '占用,占去（时间）;占据', 'Checking my phone had occupied much of my free time.', '看手机占去了我大量的空闲时间。', 'Improving Yourself', 5, 0, 'senior', 'wordlist', 'elective2', 'U2', 'occupy one''s time', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'profile', 'n.', '/ˈprəʊfaɪl/', '概况;个人简介', 'We used to post photos and update our profiles every day.', '我们过去每天都发照片、更新自己的个人简介。', 'Improving Yourself', 6, 0, 'senior', 'wordlist', 'elective2', 'U2', 'update one''s profile', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'distract', 'v.', '/dɪˈstrækt/', '分散（注意力）;使分心', 'Endless messages can distract us from real conversations.', '没完没了的消息会让我们从真实的交谈中分心。', 'Improving Yourself', 7, 0, 'senior', 'wordlist', 'elective2', 'U2', 'distract sb from', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'constantly', 'adv.', '/ˈkɒnstəntli/', '持续不断地;经常地', 'Was I really missing out by constantly checking my phone?', '不停地看手机，我真的错过了什么吗？', 'Improving Yourself', 8, 0, 'senior', 'wordlist', 'elective2', 'U2', 'constantly checking', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'towel', 'n.', '/ˈtaʊəl/', '毛巾', 'She handed me a clean towel after the swim.', '游完泳后她递给我一条干净的毛巾。', 'Improving Yourself', 9, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a clean towel', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'throw in the towel', 'phr.', '/θrəʊ ɪn ðə ˈtaʊəl/', '认输;放弃', 'I was embarrassed to throw in the towel on the very first day.', '我很尴尬，第一天就认输放弃了。', 'Improving Yourself', 10, 0, 'senior', 'wordlist', 'elective2', 'U2', 'throw in the towel', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'access', 'n.', '/ˈækses/', '接触的机会;使用权;通道', 'Without access to social media, I could not remember where the party was.', '没有社交媒体可用，我想不起聚会在哪里。', 'Improving Yourself', 11, 0, 'senior', 'wordlist', 'elective2', 'U2', 'have access to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'rely', 'v.', '/rɪˈlaɪ/', '依赖;依靠', 'The detox showed how heavily we rely on our phones.', '这次脱瘾让我们看清自己多么依赖手机。', 'Improving Yourself', 12, 0, 'senior', 'wordlist', 'elective2', 'U2', 'rely heavily', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'rely on', 'phr.', '/rɪˈlaɪ ɒn/', '依靠;依赖', 'We should not rely on social media for every bit of news.', '我们不该事事都依赖社交媒体获取消息。', 'Improving Yourself', 13, 0, 'senior', 'wordlist', 'elective2', 'U2', 'rely on social media', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'deadline', 'n.', '/ˈdedlaɪn/', '截止时间;最后期限', 'I used to be careless and never met my assignment deadlines.', '我以前很马虎，从不按时完成作业的截止期限。', 'Improving Yourself', 14, 0, 'senior', 'wordlist', 'elective2', 'U2', 'meet a deadline', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'procrastination', 'n.', '/prəˌkræstɪˈneɪʃ(ə)n/', '拖延', 'The book taught me a clever way to beat procrastination.', '这本书教了我一个战胜拖延的妙招。', 'Improving Yourself', 15, 0, 'senior', 'wordlist', 'elective2', 'U2', 'beat procrastination', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'appropriate', 'adj.', '/əˈprəʊpriət/', '恰当的;合适的', 'We talked about what appropriate behaviour means in public.', '我们讨论了在公共场合什么是恰当的行为。', 'Improving Yourself', 16, 0, 'senior', 'wordlist', 'elective2', 'U2', 'appropriate behaviour', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'spit', 'v.', '/spɪt/', '吐口水,吐唾沫', 'We should tell people not to spit in public, as it spreads diseases.', '我们应提醒人们不要在公共场合吐痰，因为这会传播疾病。', 'Improving Yourself', 17, 0, 'senior', 'wordlist', 'elective2', 'U2', 'spit in public', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'headphones', 'n.', '/ˈhedfəʊnz/', '（头戴式）耳机', 'When people talk loudly, I just put my headphones on.', '有人大声说话时，我就戴上耳机。', 'Improving Yourself', 18, 0, 'senior', 'wordlist', 'elective2', 'U2', 'put on headphones', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'bin', 'n.', '/bɪn/', '垃圾箱', 'I would ask them to put the litter into a rubbish bin.', '我会请他们把垃圾扔进垃圾箱。', 'Improving Yourself', 19, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a rubbish bin', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'considerate', 'adj.', '/kənˈsɪd(ə)rɪt/', '替他人着想的;体贴的', 'A polite reminder shows you are considerate of others.', '礼貌的提醒说明你替他人着想。', 'Improving Yourself', 20, 0, 'senior', 'wordlist', 'elective2', 'U2', 'be considerate of others', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'promote', 'v.', '/prəˈməʊt/', '促进,增进;提倡', 'The school used a clever programme to promote honesty.', '学校用一个巧妙的方案来提倡诚信。', 'Improving Yourself', 21, 0, 'senior', 'wordlist', 'elective2', 'U2', 'promote honesty', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'clarify', 'v.', '/ˈklærɪfaɪ/', '澄清,讲清楚,阐明', 'Let me clarify what I mean by giving you an example.', '让我举个例子来阐明我的意思。', 'Improving Yourself', 22, 0, 'senior', 'wordlist', 'elective2', 'U2', 'let me clarify', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'headline', 'n.', '/ˈhedlaɪn/', '媒体报道的热门话题;标题', 'Recent headlines tell of teens spending too much on online games.', '近来的热门报道讲述青少年在网络游戏上花钱过多。', 'Improving Yourself', 23, 0, 'senior', 'wordlist', 'elective2', 'U2', 'recent headlines', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'max out', 'phr.', '/mæks aʊt/', '（钱）花光;（信用卡）刷爆', 'Some teens max out their parents'' credit cards on games.', '一些青少年把父母的信用卡刷爆来玩游戏。', 'Improving Yourself', 24, 0, 'senior', 'wordlist', 'elective2', 'U2', 'max out a card', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'in contrast to', 'phr.', '/ɪn ˈkɒntrɑːst tuː/', '与……形成对比', 'In contrast to the big spenders, some teens use money wisely.', '与大手大脚的人形成对比，有些青少年用钱很明智。', 'Improving Yourself', 25, 0, 'senior', 'wordlist', 'elective2', 'U2', 'in contrast to others', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'district', 'n.', '/ˈdɪstrɪkt/', '地区,区域', 'She started making bags for homeless people in her district.', '她开始为自己所在地区的无家可归者制作袋子。', 'Improving Yourself', 26, 0, 'senior', 'wordlist', 'elective2', 'U2', 'the local district', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'necessity', 'n.', '/nɪˈsesɪti/', '必需品;必要', 'Inside the bags were necessities such as soap and socks.', '袋子里装着肥皂、袜子等必需品。', 'Improving Yourself', 27, 0, 'senior', 'wordlist', 'elective2', 'U2', 'daily necessities', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'toothpaste', 'n.', '/ˈtuːθpeɪst/', '牙膏', 'Each bag held toothpaste, soap and a clean towel.', '每个袋子里都有牙膏、肥皂和一条干净的毛巾。', 'Improving Yourself', 28, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a tube of toothpaste', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'soap', 'n.', '/səʊp/', '肥皂', 'A bar of soap was one of the most useful items in the bag.', '一块肥皂是袋子里最有用的物品之一。', 'Improving Yourself', 29, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a bar of soap', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'item', 'n.', '/ˈaɪtəm/', '一件商品（或物品）', 'These small items helped make poor people''s lives a little easier.', '这些小物品让贫困者的生活轻松了一些。', 'Improving Yourself', 30, 0, 'senior', 'wordlist', 'elective2', 'U2', 'everyday items', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'personal finances', 'phr.', '/ˈpɜːs(ə)nəl ˈfaɪnænsɪz/', '（个人的）财务管理', 'Some schools teach teenagers how to manage their personal finances.', '一些学校教青少年如何管理个人财务。', 'Improving Yourself', 31, 0, 'senior', 'wordlist', 'elective2', 'U2', 'manage personal finances', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'jar', 'n.', '/dʒɑː/', '（玻璃）罐子,广口瓶', 'He gave each child a jar for saving and a jar for giving.', '他给每个孩子一个储蓄罐和一个捐赠罐。', 'Improving Yourself', 32, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a saving jar', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'invest', 'v.', '/ɪnˈvest/', '投资', 'The fourth jar reminds us to invest in ourselves.', '第四个罐子提醒我们投资自己。', 'Improving Yourself', 33, 0, 'senior', 'wordlist', 'elective2', 'U2', 'invest in yourself', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'lifelong', 'adj.', '/ˈlaɪflɒŋ/', '终身的', 'The jars give children a chance to learn lifelong values.', '这些罐子让孩子有机会学到终身受用的价值观。', 'Improving Yourself', 34, 0, 'senior', 'wordlist', 'elective2', 'U2', 'lifelong values', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'vision', 'n.', '/ˈvɪʒ(ə)n/', '构想,设想;远见', 'Saving gives you a vision for the future.', '储蓄给你一个对未来的设想。', 'Improving Yourself', 35, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a vision for the future', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'likewise', 'adv.', '/ˈlaɪkwaɪz/', '同样地;相似地', 'She saved part of her money, and her brother did likewise.', '她存下了一部分钱，她弟弟也照样做了。', 'Improving Yourself', 36, 0, 'senior', 'wordlist', 'elective2', 'U2', 'do likewise', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'objectively', 'adv.', '/əbˈdʒektɪvli/', '客观地', 'The jars help teenagers think more objectively about money.', '这些罐子帮助青少年更客观地看待金钱。', 'Improving Yourself', 37, 0, 'senior', 'wordlist', 'elective2', 'U2', 'think objectively', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'equip', 'v.', '/ɪˈkwɪp/', '使有知识和技能;使能够胜任;装备', 'Good habits equip you to make informed choices in adult life.', '良好的习惯使你在成年后能做出明智的选择。', 'Improving Yourself', 38, 0, 'senior', 'wordlist', 'elective2', 'U2', 'be equipped to do', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'nail', 'n.', '/neɪl/', '钉子', 'Every time the boy lost his temper, he hammered a nail into the fence.', '男孩每发一次脾气，就往栅栏上钉一颗钉子。', 'Improving Yourself', 39, 0, 'senior', 'wordlist', 'elective2', 'U2', 'hammer a nail', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'moderator', 'n.', '/ˈmɒdəreɪtə/', '（论坛的）主持人;调解人', 'The moderator thanked everyone who took part in the detox.', '主持人感谢了每一位参加脱瘾活动的人。', 'Improving Yourself', 40, 0, 'senior', 'wordlist', 'elective2', 'U2', 'the forum moderator', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'detox', 'n.', '/ˈdiːtɒks/', '脱瘾;戒断（期）', 'The social media detox lasted seven full days.', '这次社交媒体脱瘾持续了整整七天。', 'Improving Yourself', 41, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a social media detox', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'fundraising', 'n.', '/ˈfʌndˌreɪzɪŋ/', '募捐,筹款', 'The detox was a fundraising campaign for new sports equipment.', '这次脱瘾是为新体育器材举办的筹款活动。', 'Improving Yourself', 42, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a fundraising campaign', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'awareness', 'n.', '/əˈweənəs/', '意识;认识;觉察', 'The campaign raised awareness of how much we depend on social media.', '这次活动让人们意识到自己多么依赖社交媒体。', 'Improving Yourself', 43, 0, 'senior', 'wordlist', 'elective2', 'U2', 'raise awareness', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'reflection', 'n.', '/rɪˈflekʃ(ə)n/', '反思;沉思;反映', 'On reflection, I saw how much time my phone had taken up.', '回头反思，我才看清手机占用了我多少时间。', 'Improving Yourself', 44, 0, 'senior', 'wordlist', 'elective2', 'U2', 'on reflection', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'temper', 'n.', '/ˈtempə/', '脾气;情绪', 'The boy learnt that it was easier to hold his temper than to hammer nails.', '男孩懂得了控制脾气比钉钉子要容易。', 'Improving Yourself', 45, 0, 'senior', 'wordlist', 'elective2', 'U2', 'lose one''s temper', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'anger', 'n.', '/ˈæŋɡə/', '愤怒;怒火', 'When you speak in anger, it can leave a hole in someone''s heart.', '你愤怒时说出的话，会在别人心里留下伤口。', 'Improving Yourself', 46, 0, 'senior', 'wordlist', 'elective2', 'U2', 'control one''s anger', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'responsible', 'adj.', '/rɪˈspɒnsəb(ə)l/', '负责的;有责任的', 'The Spending jar teaches that you are responsible for your own happiness.', '消费罐告诉你，你要为自己的幸福负责。', 'Improving Yourself', 47, 0, 'senior', 'wordlist', 'elective2', 'U2', 'be responsible for', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'value', 'n.', '/ˈvæljuː/', '价值;价值观;意义', 'The detox made me realise the value of real, face-to-face contact.', '这次脱瘾让我意识到真实面对面交流的价值。', 'Improving Yourself', 48, 0, 'senior', 'wordlist', 'elective2', 'U2', 'lifelong values', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe2u2.01', '①had been done:过去某动作之前主语「被」做了某事', 'A2', 11, '外研社版选择性必修第二册 U2 — 主语是动作的承受者、且这件事发生在过去某个时间点之前时，用 had been + 过去分词。错项要么是主动（had done）、要么是错时态（was done / has been done）。', 1, 'elective2', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe2u2.02', '②had been done vs had done:主语「被」做还是「主动」做', 'A2', 11, '外研社版选择性必修第二册 U2 — 在「过去之前已完成」的语境里，先判断主语是承受动作还是发出动作:承受用 had been done，发出用 had done。看错语态即排除。', 2, 'elective2', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe2u2.03', '③had been done vs was done:before / by the time 逼出过去完成', 'A2', 11, '外研社版选择性必修第二册 U2 — 都是被动，但有 before / by the time + 过去 标志、表示「过去之前就已被…」时必须用 had been done，不能用一般过去被动 was done 或其它时态。', 3, 'elective2', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'At the start of the campaign, over 100 students ____ to give up social media for a week.', 'had been persuaded', 'had persuaded', 'was persuaded', 'has been persuaded', 'A', '学生是被劝说的、且发生在活动开始这一过去点之前 → had been + 过去分词。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'When Jack got home, he found that his messy homework ____ in the centre of the desk.', 'had put', 'had been put', 'was put', 'has been put', 'B', '作业是被放好的、发生在到家之前 → had been put。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'Before the new term began, all my bad study habits ____.', 'had broken', 'were broken', 'had been broken', 'have been broken', 'C', '习惯是被改掉的、在新学期开始之前 → had been broken。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'By the time Jack woke up, his untidy room ____ by his parents.', 'had cleaned', 'was cleaned', 'has been cleaned', 'had been cleaned', 'D', '房间是被打扫的、在他醒来之前 → had been cleaned。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'A small present ____ on the desk before Jack even noticed it.', 'had been left', 'had left', 'was left', 'has been left', 'A', '礼物是被留下的、在他注意到之前 → had been left。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'By last Monday, a clear to-do list ____ for the whole week.', 'had made', 'had been made', 'was made', 'has been made', 'B', '清单是被制定的、到上周一这个过去点之前 → had been made。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'Before the exam started, the rules ____ to every student.', 'had explained', 'were explained', 'had been explained', 'have been explained', 'C', '规则是被解释的、在考试开始之前 → had been explained。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'By the end of the detox, a lot of money ____ for new sports equipment.', 'had raised', 'was raised', 'has been raised', 'had been raised', 'D', '钱是被筹集的、到脱瘾结束之前 → had been raised。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'When she woke up, her phone ____ in a drawer by her mum.', 'had been put', 'had put', 'was put', 'has been put', 'A', '手机是被放进抽屉的、在她醒来之前 → had been put。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'Before I joined the club, I ____ to set a daily goal.', 'had motivated', 'had been motivated', 'was motivated', 'have been motivated', 'B', '「我」是被激励的、在加入俱乐部之前 → had been motivated。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'By noon, all the umbrellas ____ to the school in good condition.', 'had returned', 'were returned', 'had been returned', 'have been returned', 'C', '伞是被归还的、到中午这个过去点之前 → had been returned。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'Before the talk ended, several good examples ____ by the speaker.', 'had given', 'were given', 'has been given', 'had been given', 'D', '例子是被给出的、在演讲结束之前 → had been given。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'By the time the bell rang, the test papers ____ already.', 'had been collected', 'had collected', 'were collected', 'have been collected', 'A', '试卷是被收走的、在铃响之前 → had been collected。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'When the teacher arrived, the seats ____ in neat rows.', 'had arranged', 'had been arranged', 'were arranged', 'has been arranged', 'B', '座位是被摆好的、在老师到达之前 → had been arranged。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'Before he turned over a new leaf, his deadlines ____ again and again.', 'had missed', 'were missed', 'had been missed', 'have been missed', 'C', '截止期限是被错过的、在他改过自新之前 → had been missed。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'By Friday, the whole project ____ two days early.', 'had finished', 'was finished', 'has been finished', 'had been finished', 'D', '项目是被完成的、到周五之前 → had been finished。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'When the guests arrived, the meeting room ____ for them.', 'had been prepared', 'had prepared', 'was prepared', 'has been prepared', 'A', '房间是被布置的、在客人到达之前 → had been prepared。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'Before the campaign ended, a clear message ____ to everyone.', 'had sent', 'had been sent', 'was sent', 'has been sent', 'B', '信息是被发送的、在活动结束之前 → had been sent。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'By the time we met, the new plan ____ into action.', 'had put', 'was put', 'had been put', 'have been put', 'C', '计划是被付诸行动的、在我们见面之前 → had been put。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.01'), 'Before the new term, all the old notes ____ away.', 'had thrown', 'were thrown', 'has been thrown', 'had been thrown', 'D', '笔记是被扔掉的、在新学期之前 → had been thrown。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'By the time the bell rang, Jack ____ all his homework.', 'had done', 'had been done', 'was doing', 'has done', 'A', 'Jack 是动作的发出者（他做作业）→ 主动 had done，不用被动。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'Before the meeting started, the manager ____ a clear plan.', 'had been prepared', 'had prepared', 'was preparing', 'has prepared', 'B', '经理主动制定计划 → had prepared。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'By last week, Anna ____ a brand-new study habit on her own.', 'had been started', 'was starting', 'had started', 'has started', 'C', 'Anna 主动养成习惯 → had started。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'Before the deadline, the students ____ in their reports.', 'had been handed', 'were handing', 'have handed', 'had handed', 'D', '学生主动上交报告 → had handed。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'By the time we arrived, Grandpa ____ the whole story to the children.', 'had told', 'had been told', 'was telling', 'has told', 'A', '爷爷主动讲故事 → had told。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'Before he gave up his phone, Max ____ social media every single hour.', 'had been checked', 'had checked', 'was checking', 'has checked', 'B', 'Max 主动刷社交媒体 → had checked。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'By Sunday, Cindy ____ a different friend every day of the detox.', 'had been visited', 'was visiting', 'had visited', 'has visited', 'C', 'Cindy 主动去拜访朋友 → had visited。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'Before the term ended, the teacher ____ us a lot of useful advice.', 'had been given', 'was giving', 'has given', 'had given', 'D', '老师主动给建议 → had given。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'By the time his mum came home, the boy ____ many nails into the fence.', 'had hammered', 'had been hammered', 'was hammering', 'has hammered', 'A', '男孩主动钉钉子 → had hammered。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'Before the talk, Ms Wu ____ several examples ready in her mind.', 'had been got', 'had got', 'was getting', 'has got', 'B', '吴老师主动准备好例子 → had got。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'At the start of the detox, over 100 students ____ to take part.', 'had persuaded', 'was persuading', 'had been persuaded', 'has persuaded', 'C', '学生是被劝说参加的 → had been persuaded。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'Before the exam began, the rules ____ to everyone in the hall.', 'had explained', 'was explaining', 'has explained', 'had been explained', 'D', '规则是被解释的 → had been explained。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'By noon, all the umbrellas ____ to the school office.', 'had been returned', 'had returned', 'were returning', 'have returned', 'A', '伞是被归还的 → had been returned。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'Before Jack noticed it, a present ____ on his clean desk.', 'had left', 'had been left', 'was leaving', 'has left', 'B', '礼物是被留下的 → had been left。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'By the end of term, a culture of honesty ____ across the whole school.', 'had built', 'was building', 'had been built', 'has built', 'C', '诚信文化是被建立起来的 → had been built。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'Before the new rule, the messy room ____ many times by his parents.', 'had cleaned', 'was cleaning', 'has cleaned', 'had been cleaned', 'D', '房间是被父母打扫的 → had been cleaned。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'By the time he woke up, his phone ____ in a drawer for safety.', 'had been put', 'had put', 'was putting', 'has put', 'A', '手机是被放进抽屉的 → had been put。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'Before the campaign ended, a large sum of money ____ for sports equipment.', 'had raised', 'had been raised', 'was raising', 'has raised', 'B', '钱是被筹集的 → had been raised。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'By Monday, the good news ____ to every class in the school.', 'had spread', 'was spreading', 'had been spread', 'has spread', 'C', '消息是被传开的 → had been spread。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.02'), 'Before the lesson, the desks ____ in neat, tidy rows.', 'had arranged', 'was arranging', 'has arranged', 'had been arranged', 'D', '课桌是被摆放整齐的 → had been arranged。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'By the time the teacher arrived, the test papers ____ already.', 'had been collected', 'were collected', 'are collected', 'has been collected', 'A', 'by the time + 过去，强调过去之前就被收走 → had been collected，不用一般过去被动。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'Before the detox started, over 100 students ____ to join in.', 'were persuaded', 'had been persuaded', 'are persuaded', 'has been persuaded', 'B', 'before + 过去，发生在脱瘾开始之前 → had been persuaded。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'By the time we got there, all the prizes ____ out.', 'were given', 'are given', 'had been given', 'have been given', 'C', 'by the time 标志，奖品在我们到达之前已被发完 → had been given。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'Before Jack came home, his messy room ____ from top to bottom.', 'was tidied', 'is tidied', 'has been tidied', 'had been tidied', 'D', 'before + 过去，房间在他回家前已被收拾 → had been tidied。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'By the time the bell rang, the homework ____ in.', 'had been handed', 'was handed', 'is handed', 'has been handed', 'A', 'by the time 标志 → had been handed。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'Before the new term began, the timetable ____ for every class.', 'was set', 'had been set', 'is set', 'has been set', 'B', 'before + 过去 → had been set。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'By the time his mum checked, the phone ____ away safely.', 'was put', 'is put', 'had been put', 'has been put', 'C', 'by the time 标志 → had been put。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'Before the speech ended, the main idea ____ clearly to the audience.', 'was expressed', 'is expressed', 'has been expressed', 'had been expressed', 'D', 'before + 过去 → had been expressed。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'By the time the guests arrived, a big meal ____ for them.', 'had been cooked', 'was cooked', 'is cooked', 'has been cooked', 'A', 'by the time 标志 → had been cooked。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'Before the umbrellas were returned, a short message ____ on each one.', 'was printed', 'had been printed', 'is printed', 'has been printed', 'B', 'before + 过去 → had been printed。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'By the time I joined the club, the rules ____ already.', 'were explained', 'are explained', 'had been explained', 'have been explained', 'C', 'by the time 标志 → had been explained。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'Before the holiday started, every library book ____ on time.', 'was returned', 'is returned', 'has been returned', 'had been returned', 'D', 'before + 过去 → had been returned。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'By the time the campaign closed, a lot of awareness ____.', 'had been raised', 'was raised', 'is raised', 'has been raised', 'A', 'by the time 标志 → had been raised。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'Before the exam, the desks ____ far apart from one another.', 'were moved', 'had been moved', 'are moved', 'have been moved', 'B', 'before + 过去 → had been moved。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'By the time he said sorry, the harm ____ already.', 'was done', 'is done', 'had been done', 'has been done', 'C', 'by the time 标志，伤害在道歉之前已经造成 → had been done。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'Before the meeting, the report ____ to all the members.', 'was sent', 'is sent', 'has been sent', 'had been sent', 'D', 'before + 过去 → had been sent。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'By the time we woke up, breakfast ____ in the kitchen.', 'had been prepared', 'was prepared', 'is prepared', 'has been prepared', 'A', 'by the time 标志 → had been prepared。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'Before he made the new plan, his time ____ on the phone.', 'was wasted', 'had been wasted', 'is wasted', 'has been wasted', 'B', 'before + 过去 → had been wasted。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'By the time the teacher returned, the question ____ on the board.', 'was answered', 'is answered', 'had been answered', 'have been answered', 'C', 'by the time 标志 → had been answered。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U2' AND code='fe2u2.03'), 'Before the lesson ended, the new words ____ twice for us.', 'were repeated', 'are repeated', 'has been repeated', 'had been repeated', 'D', 'before + 过去 → had been repeated。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Seven Days Without a Phone', 'At Brenton High, a special challenge was set up as a way of raising money for new sports equipment. Before the challenge started, more than a hundred students had been persuaded to stop using social media for a whole week. That meant no messaging, no photos and no updating of profiles. Many found the first days hard. One girl said she felt as if she had lost an arm, because so much of her time had been taken up by checking her phone. Others discovered something better. Instead of sending a message, one student walked to her friend''s house and they talked for two hours without being distracted. By the fifth day she wondered whether she had really been missing anything at all. In the end the detox raised over sixteen hundred pounds. But the moderator noticed that something else had also grown: an awareness of how much everyone relied on their phones, and a wish to talk to one another more.', '记叙·社交媒体脱瘾', 162, '[{"q":"Why was the challenge organised in the first place?","answer":"A","options":["To raise funds for the school''s new sporting gear.","To punish students who used phones.","To test the school''s Internet speed.","To stop students playing any sport."],"explanation":"原文说 a way of raising money for new sports equipment，选项是其转述。"},{"q":"What did the girl who walked to her friend''s house realise?","answer":"B","options":["She would never use a phone again.","She had probably not been missing much by leaving her phone.","Her friend no longer liked her.","Talking face to face was boring."],"explanation":"她第五天怀疑自己其实没错过什么，是对 wondered whether she had really been missing anything 的概括。"},{"q":"Besides money, what did the moderator say had grown?","answer":"A","options":["People''s understanding of how much they depended on phones.","The number of phones sold at school.","The amount of time spent online.","The students'' dislike of sport."],"explanation":"末段 an awareness of how much everyone relied on their phones 的转述。"}]'::jsonb, '[{"word":"detox","cn":"脱瘾"},{"word":"moderator","cn":"主持人"},{"word":"distracted","cn":"分心的"}]'::jsonb, 2, 'elective2', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A Clever Way to Beat Procrastination', 'Jack used to be a lazy student. He was careless about homework, and none of his deadlines had ever been met. He would even hide his homework in his messy room so that he could put off doing it. Then he read a book called The Art of Procrastination, written by John Perry. The author explained that putting things off is really about avoiding the hardest and most important tasks. So Perry gave a clever piece of advice. Instead of placing your homework at the top of your list, put it second or third. Then put one or two really hard jobs that you hate at the very top. Because you want to avoid those terrible tasks, you will happily do your homework instead, just to escape them. In this way, your wish to delay actually pushes you to finish useful work. Jack tried it, and slowly the habit of leaving everything until the last minute began to disappear.', '说明·战胜拖延', 159, '[{"q":"What was Jack like before he read the book?","answer":"B","options":["He always finished tasks early.","He delayed his work and missed his deadlines.","He had the tidiest room in school.","He never had any homework."],"explanation":"原文说他懒散、deadlines had ever been met 的否定形式，选项是概括。"},{"q":"According to John Perry, what is procrastination really about?","answer":"C","options":["Doing easy work very slowly.","Forgetting all your tasks.","Staying away from the toughest and most important jobs.","Working hard all night long."],"explanation":"avoiding the hardest and most important tasks 的转述。"},{"q":"How does Perry''s trick make you finish your homework?","answer":"D","options":["It removes homework from the list completely.","It gives you a money reward each time.","It makes the homework much shorter.","You do it to escape even harder tasks placed above it."],"explanation":"把更难的任务放在最上面，为逃避它们而去做作业，是对该方法的概括。"}]'::jsonb, '[{"word":"procrastination","cn":"拖延"},{"word":"deadline","cn":"截止时间"},{"word":"put off","cn":"推迟"}]'::jsonb, 2, 'elective2', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Four Jars and a Lifelong Lesson', 'When Jerry Witkovsky''s grandchildren turned thirteen, he did not simply give them money. Instead, each child received several glass jars, one labelled Spending, one Saving and one Giving. Later he added a fourth jar for Investing. From then on, the children had to decide for themselves what to do with the money they received. The Spending jar teaches that you are responsible for your own happiness, and that it is fine to treat yourself once in a while. The Saving jar gives you a vision for the future, perhaps for university or for something special you have seen. The Investing jar is about building for the future and putting money into yourself. The Giving jar is all about kindness, letting you support any cause you believe in. Jerry''s real present was not the cash inside the jars. It was the chance to learn lifelong values and to think more objectively about money, so that as adults the children would make wiser choices.', '说明·四个储蓄罐', 162, '[{"q":"What did Jerry give his grandchildren instead of just money?","answer":"A","options":["Several jars that taught them how to manage what they had.","A list of expensive toys to buy.","A bank card with no limit.","A holiday abroad every year."],"explanation":"each child received several glass jars 的转述，强调用来管理金钱。"},{"q":"What lesson does the Saving jar mainly teach?","answer":"B","options":["To spend everything at once.","To look ahead and plan for things you may want later.","To give all your money away.","To hide money from your family."],"explanation":"gives you a vision for the future 的概括。"},{"q":"What was Jerry''s real present to the children?","answer":"C","options":["A large sum of cash inside the jars.","Four empty glass bottles.","The chance to learn values that would last all their lives.","A book about getting rich quickly."],"explanation":"the chance to learn lifelong values 的转述。"}]'::jsonb, '[{"word":"jar","cn":"罐子"},{"word":"invest","cn":"投资"},{"word":"vision","cn":"构想"}]'::jsonb, 2, 'elective2', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Nails in the Fence', 'There was once a boy who could not control his temper. His father gave him a bag of nails and told him that every time he lost his temper he must hammer a nail into the back of the fence. On the first day the boy drove in so many nails that the bag was soon empty. But over the next few weeks he learnt to hold his anger, and the number of nails grew smaller each day. He found that it was far easier to control himself than to hammer nail after nail. At last came a day when he did not lose his temper even once. His father then told him to pull out one nail for every calm day. When all the nails were finally gone, the father led him to the fence and pointed at the holes left behind. He said that angry words leave marks just like those holes, and that saying sorry cannot always take them away.', '记叙·钉子与脾气', 163, '[{"q":"What did the father ask the boy to do whenever he got angry?","answer":"D","options":["Pull a nail out at once.","Write down his feelings.","Pay a small fine.","Drive a nail into the fence."],"explanation":"hammer a nail into the back of the fence 的转述。"},{"q":"What did the boy discover over the following weeks?","answer":"A","options":["Keeping calm was easier than hammering more nails.","Hammering nails was great fun.","His father was always unfair.","The fence needed more nails."],"explanation":"easier to control himself than to hammer nail after nail 的概括。"},{"q":"What lesson did the holes in the fence teach?","answer":"B","options":["Fences should never have nails.","Hurtful words can leave marks that an apology may not remove.","It is good to say sorry many times.","Anger has no effect on others."],"explanation":"angry words leave marks like those holes, saying sorry cannot always take them away 的转述。"}]'::jsonb, '[{"word":"temper","cn":"脾气"},{"word":"nail","cn":"钉子"},{"word":"anger","cn":"愤怒"}]'::jsonb, 2, 'elective2', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Trusting Students to Be Honest', 'A school in our city came up with an unusual programme to promote the value of honesty. To begin with, it introduced what was called the unsupervised examination. During this kind of test, there was no teacher watching the room at all. Before they were allowed to take it, students first had to make a promise to behave honestly. Most of them said it felt good to be trusted, and they really enjoyed the freedom such a test offered. In turn, they developed a stronger sense of responsibility towards their own work. The school also gave out umbrellas that anyone could borrow. Printed on each umbrella was a short line about honesty. At the end of the term, every single umbrella had been returned, and not one of them had been lost or damaged. The head teacher, Ms Wu, now hopes to share the idea with other schools, because building a culture of trust needs everybody to take part.', '新闻·无人监考与诚信', 159, '[{"q":"What was special about the unsupervised examination?","answer":"C","options":["Students could copy from books.","It lasted only five minutes.","No teacher stayed in the room to watch the students.","Only the best students could sit it."],"explanation":"there was no teacher watching the room 的转述。"},{"q":"How did most students feel about being trusted?","answer":"D","options":["They were angry and refused to take part.","They felt bored throughout.","They wished a teacher would watch them.","They were pleased and enjoyed the freedom it gave."],"explanation":"it felt good to be trusted, enjoyed the freedom 的概括。"},{"q":"What happened to the borrowed umbrellas by the end of term?","answer":"A","options":["They all came back undamaged.","Most of them were lost.","Half of them were broken.","Nobody borrowed any of them."],"explanation":"every single umbrella had been returned, none lost or damaged 的转述。"}]'::jsonb, '[{"word":"promote","cn":"促进"},{"word":"unsupervised","cn":"无人监督的"},{"word":"responsibility","cn":"责任感"}]'::jsonb, 2, 'elective2', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Small Hands, Big Hearts', 'While some teenagers max out their parents'' cards on games, others prove that age is no barrier to using money well. With help from her grandmother, an eight-year-old girl named Khloe Thompson began making simple bags for homeless people in her district. Inside each bag she placed everyday necessities such as toothpaste, soap and socks. At first these things were bought with her own pocket money. Later, when more people heard about her idea, she raised money online so that she could make many more bags. The items were small, but they helped to make hard lives a little easier. One woman who received a bag told Khloe that the gift made her feel like a human being again. Khloe''s story shows that you do not need to be rich or grown up to improve the world around you. A kind idea, a little effort and a willing heart can already make a real difference to others.', '记叙·小小善举', 157, '[{"q":"What did Khloe Thompson make for homeless people?","answer":"B","options":["Toys for their children.","Bags filled with daily necessities.","Tickets to a football match.","New mobile phones."],"explanation":"making simple bags... necessities such as toothpaste, soap and socks 的转述。"},{"q":"How did Khloe pay for the bags after her idea became known?","answer":"C","options":["Her school gave her a salary.","She sold her own toys.","She collected money from people online.","She borrowed from a bank."],"explanation":"she raised money online 的转述。"},{"q":"What is the main message of Khloe''s story?","answer":"D","options":["Only rich adults can do good.","Giving money is a waste.","Homeless people cannot be helped.","Even the young and ordinary can help others."],"explanation":"you do not need to be rich or grown up to improve the world 的概括。"}]'::jsonb, '[{"word":"necessity","cn":"必需品"},{"word":"district","cn":"地区"},{"word":"max out","cn":"刷爆"}]'::jsonb, 2, 'elective2', 'U2', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U2', 'My New Morning Habit', 'Last term I decided to (1)____ myself by getting up earlier. At first it was really (2)____, because my warm bed was hard to leave. But I knew that the quiet early hours could be the best (3)____ to study. So I set my alarm and put the clock far from my (4)____, so I had to stand up to switch it off. After a week, my body got (5)____ to the new time. I would read English for half an hour before breakfast, when nothing could (6)____ me. Slowly, this small (7)____ changed my whole day. I felt calmer, and my marks began to (8)____. My friends asked me for (9)____, and I told them that the secret was not talent but a steady (10)____. A good morning, I learnt, can shape the rest of the day.', 138, 2, '[{"q":"1","answer":"A","options":["improve","forget","waste","lose"],"explanation":"improve myself 完善自己。"},{"q":"2","answer":"B","options":["easy","hard","funny","free"],"explanation":"起初很难 → hard。"},{"q":"3","answer":"C","options":["price","noise","time","colour"],"explanation":"the best time to study 学习的最佳时间。"},{"q":"4","answer":"D","options":["school","garden","shop","bed"],"explanation":"把钟放离床远点 → bed。"},{"q":"5","answer":"A","options":["used","afraid","rich","late"],"explanation":"get used to 习惯于。"},{"q":"6","answer":"B","options":["help","distract","teach","follow"],"explanation":"nothing could distract me 没什么能让我分心。"},{"q":"7","answer":"C","options":["price","river","habit","machine"],"explanation":"this small habit 这个小习惯。"},{"q":"8","answer":"D","options":["fall","stop","close","rise"],"explanation":"marks began to rise 成绩开始上升。"},{"q":"9","answer":"A","options":["advice","money","food","water"],"explanation":"asked me for advice 向我请教建议。"},{"q":"10","answer":"B","options":["price","habit","ticket","garden"],"explanation":"a steady habit 稳定的习惯。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U2', 'Less Time on My Phone', 'I used to pick up my phone every few minutes, even when no message had (1)____. It (2)____ so much of my time that I had almost none left for my hobbies. One evening I decided to make a (3)____. From then on, I would (4)____ off my phone while doing homework and put it in another room. The first days were (5)____, and my hand kept reaching for a phone that was not there. But soon I noticed that I could (6)____ on my books much better. I also began to (7)____ less on social media for news and fun. Instead, I read real books and went (8)____ with friends. I felt more (9)____ of my own time, not controlled by a small screen. Now I still use my phone, but I am the one who (10)____ when, not the phone.', 142, 2, '[{"q":"1","answer":"C","options":["left","sold","arrived","cooked"],"explanation":"no message had arrived 没有消息到来。"},{"q":"2","answer":"D","options":["saved","gave","missed","occupied"],"explanation":"occupied so much of my time 占用了很多时间。"},{"q":"3","answer":"A","options":["change","noise","price","hole"],"explanation":"make a change 做出改变。"},{"q":"4","answer":"B","options":["throw","switch","cut","fall"],"explanation":"switch off my phone 关掉手机。"},{"q":"5","answer":"C","options":["easy","cheap","hard","warm"],"explanation":"起初几天很难 → hard。"},{"q":"6","answer":"D","options":["spend","depend","give","focus"],"explanation":"focus on my books 专注于书本。"},{"q":"7","answer":"A","options":["rely","win","carry","build"],"explanation":"rely less on social media 少依赖社交媒体。"},{"q":"8","answer":"B","options":["down","out","off","away"],"explanation":"went out with friends 和朋友出去。"},{"q":"9","answer":"C","options":["afraid","tired","aware","bored"],"explanation":"more aware of my own time 更清楚自己的时间。"},{"q":"10","answer":"D","options":["forgets","loses","sells","decides"],"explanation":"I am the one who decides 由我决定。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U2', 'Learning to Save', 'When I was twelve, I wanted to buy a new bike, but I never seemed to have any (1)____ left. My mother gave me an empty (2)____ and a simple idea: every week, put a little money inside before spending the (3)____. At first it was (4)____ to drop in even a few coins, because I wanted to buy snacks at once. But slowly the jar grew (5)____. Watching it fill up gave me a clear (6)____ of my goal. I learnt to think more (7)____ about what I really needed and what I only wanted. Six months later, I had (8)____ enough to buy the bike with my own money. The proudest part was not the bike itself, but the (9)____ I had learnt. Saving, I discovered, is a skill that can (10)____ you for the rest of your life.', 141, 2, '[{"q":"1","answer":"A","options":["money","time","noise","water"],"explanation":"no money left 没剩下钱。"},{"q":"2","answer":"B","options":["book","jar","bus","door"],"explanation":"an empty jar 一个空罐子。"},{"q":"3","answer":"C","options":["noise","hole","rest","price"],"explanation":"spending the rest 再花剩下的。"},{"q":"4","answer":"D","options":["easy","free","late","hard"],"explanation":"起初很难 → hard。"},{"q":"5","answer":"A","options":["heavier","smaller","shorter","colder"],"explanation":"罐子越来越重 → heavier。"},{"q":"6","answer":"B","options":["price","vision","noise","smell"],"explanation":"a clear vision of my goal 对目标清晰的构想。"},{"q":"7","answer":"C","options":["loudly","slowly","objectively","sadly"],"explanation":"think more objectively 更客观地思考。"},{"q":"8","answer":"D","options":["lost","broken","sold","saved"],"explanation":"had saved enough 攒够了。"},{"q":"9","answer":"A","options":["lesson","ticket","machine","garden"],"explanation":"the lesson I had learnt 学到的一课。"},{"q":"10","answer":"B","options":["stop","help","hurt","leave"],"explanation":"a skill that can help you 能帮助你的技能。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U2', 'Counting to Ten', 'I used to lose my (1)____ very easily. The smallest thing could make me shout, and afterwards I always felt (2)____. My grandfather noticed this and taught me a simple (3)____. Whenever I felt anger rising, I should stop and slowly (4)____ to ten before saying a word. The first time I tried it, I was so cross that I almost (5)____. But I forced myself to breathe and count. By the time I reached ten, the worst of my anger had already (6)____ away. I began to (7)____ that angry words, once spoken, are very hard to take back. Like nails hammered into wood, they can leave a (8)____ behind. These days I am much (9)____, and my friends say I am easier to talk to. Learning to control my temper has been one of the best (10)____ I have ever made.', 143, 2, '[{"q":"1","answer":"C","options":["money","book","temper","key"],"explanation":"lose my temper 发脾气。"},{"q":"2","answer":"D","options":["happy","proud","rich","sorry"],"explanation":"afterwards felt sorry 事后感到后悔。"},{"q":"3","answer":"A","options":["trick","price","noise","hole"],"explanation":"a simple trick 一个简单的办法。"},{"q":"4","answer":"B","options":["sell","count","throw","drive"],"explanation":"count to ten 数到十。"},{"q":"5","answer":"C","options":["woke up","set off","gave up","sat down"],"explanation":"几乎要放弃 → gave up。"},{"q":"6","answer":"D","options":["grown","come","stayed","gone"],"explanation":"anger had gone away 怒气已消。"},{"q":"7","answer":"A","options":["realise","forget","doubt","refuse"],"explanation":"began to realise 开始意识到。"},{"q":"8","answer":"B","options":["song","mark","price","smell"],"explanation":"leave a mark behind 留下痕迹。"},{"q":"9","answer":"C","options":["louder","richer","calmer","taller"],"explanation":"much calmer 平静多了。"},{"q":"10","answer":"D","options":["noises","prices","tickets","choices"],"explanation":"one of the best choices 最好的选择之一。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U2', 'A Person of My Word', 'My class once carried out a small test of (1)____. The teacher left a box of pens on her desk and told us to take only one (2)____, writing our names in a book. There was no teacher (3)____ the room, so we were completely (4)____. At first some of us were tempted to take more, but most chose to be (5)____. It felt good to be (6)____ by our teacher, and nobody wanted to break that trust. In the end, every pen was (7)____ for, and the numbers matched exactly. Our teacher said that being honest when no one is (8)____ is the truest test of character. From that day, I tried hard to keep every (9)____ I made, however small. Being a person of my word, I found, makes others (10)____ you and makes you respect yourself.', 139, 2, '[{"q":"1","answer":"A","options":["honesty","weather","noise","speed"],"explanation":"a test of honesty 诚信测试。"},{"q":"2","answer":"B","options":["never","each","again","twice"],"explanation":"take only one each 每人只拿一支。"},{"q":"3","answer":"C","options":["selling","cleaning","watching","painting"],"explanation":"no teacher watching the room 没人监视。"},{"q":"4","answer":"D","options":["afraid","tired","famous","trusted"],"explanation":"完全被信任 → trusted。"},{"q":"5","answer":"A","options":["honest","lazy","rude","noisy"],"explanation":"chose to be honest 选择诚实。"},{"q":"6","answer":"B","options":["blamed","trusted","watched","paid"],"explanation":"felt good to be trusted 被信任的感觉很好。"},{"q":"7","answer":"C","options":["looked","waited","accounted","asked"],"explanation":"every pen was accounted for 每支笔都对得上。"},{"q":"8","answer":"D","options":["sleeping","eating","leaving","looking"],"explanation":"when no one is looking 没人看着时。"},{"q":"9","answer":"A","options":["promise","price","ticket","noise"],"explanation":"keep every promise 信守每个承诺。"},{"q":"10","answer":"B","options":["doubt","trust","forget","lose"],"explanation":"makes others trust you 让别人信任你。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U2', 'The List That Works', 'I always had too much to do and never knew where to (1)____. Important tasks were often (2)____ until the last minute, while easy ones got done first. Then a friend showed me a useful (3)____: write a to-do list every morning. At the top I put the one or two jobs I least wanted to (4)____. Strangely, this made me far more (5)____. To escape those hard tasks, I happily finished the smaller ones, and step by step the list got (6)____. Crossing out each finished job gave me a real sense of (7)____. I no longer felt (8)____ by a mountain of work. The list also helped me use my time more (9)____, so I had more free hours in the evening. A few minutes of planning each morning, I learnt, can (10)____ you a whole day of stress.', 141, 2, '[{"q":"1","answer":"C","options":["sleep","sell","start","sing"],"explanation":"where to start 从哪开始。"},{"q":"2","answer":"D","options":["finished","praised","cleaned","delayed"],"explanation":"tasks were often delayed 任务常被拖延。"},{"q":"3","answer":"A","options":["tip","price","noise","hole"],"explanation":"a useful tip 一个有用的建议。"},{"q":"4","answer":"B","options":["sell","face","throw","lose"],"explanation":"jobs I least wanted to face 最不想面对的工作。"},{"q":"5","answer":"C","options":["tired","angry","productive","hungry"],"explanation":"far more productive 高效得多。"},{"q":"6","answer":"D","options":["longer","louder","heavier","shorter"],"explanation":"the list got shorter 清单越来越短。"},{"q":"7","answer":"A","options":["progress","danger","noise","weather"],"explanation":"a sense of progress 进步感。"},{"q":"8","answer":"B","options":["praised","buried","trusted","invited"],"explanation":"felt buried by work 被工作压垮。"},{"q":"9","answer":"C","options":["loudly","slowly","wisely","sadly"],"explanation":"use my time more wisely 更明智地用时间。"},{"q":"10","answer":"D","options":["cost","give","sell","save"],"explanation":"save you a whole day of stress 替你省去一天的压力。"}]'::jsonb, 6, 'fltrp');
