INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·短文 A Good Morning Routine', '外研社版选择性必修第二册 U2 · passage', 2, 'Many successful students say the secret is a good morning routine.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·对话 Saving My Pocket Money', '外研社版选择性必修第二册 U2 · dialogue', 3, 'Ben: Mum, I really want that bike, but I never have enough money.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·短文 Hard Tasks First', '外研社版选择性必修第二册 U2 · passage', 2, 'Here is a simple way to stop putting things off.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·对话 Keeping My Cool', '外研社版选择性必修第二册 U2 · dialogue', 3, 'Anna: I shouted at my little brother again, and now I feel terrible.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·短文 Being Trusted', '外研社版选择性必修第二册 U2 · passage', 2, 'Our school once gave out umbrellas that anyone could borrow.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Write a Reflection on Improving Yourself(写一篇关于完善自己的反思)', 'How I Changed a Bad Habit', '假设你叫李华。学校英语周刊正在征集''完善自己''主题的短文。请用英语写一篇约90词的反思,内容包括:① 描述你曾经的一个坏习惯(如熬夜刷手机、拖延、乱发脾气);② 你是怎样一步步改掉它的;③ 你从中学到了什么。注意:在合适处使用过去完成被动语态(had been done)。', 'Suppose you are Li Hua. Your school''s English weekly is collecting short pieces on the theme ''Improving Yourself''. Write a reflection (about 90 words) including: 1) a bad habit you used to have (e.g. using your phone late at night, putting things off, losing your temper); 2) how you changed it step by step; 3) what you learnt from the experience. Use the past perfect passive (had been done) where it fits.', '["描述坏习惯(I used to … / My biggest problem was …)","改变过程(So I decided to … / Step by step, I …)","用过去完成被动(Before …, my time had been wasted on …)","收获与感悟(I learnt that … / Now I feel …)"]'::jsonb, 70, 100, 'I used to spend hours on my phone every night, and my homework was often left until the last minute. Before I made a change, much of my evening had been wasted on social media. So I decided to switch off my phone and put it in another room while I studied. The first days were hard, but step by step the habit was broken. By the end of the term, my marks had been raised and I felt calmer. I learnt that small daily efforts can truly improve who you are.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Before I made a change, much of my evening had been wasted on social media.","I decided to switch off my phone and put it in another room while I studied.","Step by step, the bad habit was broken.","I learnt that small daily efforts can truly improve who you are."]'::jsonb, '[{"wrong":"Before I changed, my time had wasted on my phone.","correct":"Before I changed, my time had been wasted on my phone.","note":"time 是被浪费的,主语是承受者,要用 had been done。"},{"wrong":"My homework was often leave until the last minute.","correct":"My homework was often left until the last minute.","note":"被动语态用过去分词 left,不用动词原形。"},{"wrong":"I used to spending hours on my phone.","correct":"I used to spend hours on my phone.","note":"used to do sth 后接动词原形。"}]'::jsonb, '【完善自己·反思结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective2', 'U2', '{"title":"过去完成被动语态 had been done 速查","intro":"had been + 过去分词,表示「在过去某个时间点之前,主语已经『被』做了某事」。两个关键:① 主语是动作的承受者(被动);② 这件事发生在另一过去动作之前(过去的过去)。","table":{"headers":["结构 / 用法","例句"],"rows":[["肯定:had been + 过去分词","Over 100 students had been persuaded to join. 100多名学生已被劝说参加。"],["否定:had not been + 过去分词","None of the umbrellas had been lost. 没有一把伞丢失。"],["疑问:Had + 主语 + been + 过去分词?","Had the homework been finished by then? 那时作业完成了吗?"],["常见时间标志","by the time …, before …, by + 过去时间点"]]},"specialRules":[{"rule":"主语『被』做 → 被动 had been done;主语『主动』做 → had done","mark":"The room had been cleaned(房间被打扫) vs He had cleaned the room(他打扫了房间)"},{"rule":"有 before / by the time + 过去 → 用 had been done,不用一般过去被动 was done","mark":"By the time we arrived, the prizes had been given out."},{"rule":"过去分词形式不可写成动词原形或现在分词","mark":"had been left √ / had been leave × / had been leaving ×"},{"rule":"by + 动作发出者(可省略)","mark":"The phone had been put away (by his mum)."}],"why":["「过去完成」管时间——比另一个过去动作更早;「被动」管关系——主语是承受者。两者叠加,就是 had + been + 过去分词:在过去某点之前,某事已被完成。"],"gaokaoPoints":["语法填空/短文改错高频:给出动词原形,要求填 had been done;判断主语是受动者(用被动)还是施动者(用主动)。","易错点:有 by the time/before 标志却误填 was done(一般过去被动);或把过去分词写错形式。"],"examVsReal":[{"exam":"By the time he arrived, the work had been finished.(考试/书面)","real":"By the time he got there, the work was already done.","note":"考试严格区分『过去的过去』用 had been done;口语里有时用 was done + already 也能表达先后"},{"exam":"The umbrellas had all been returned.(强调过去之前已完成)","real":"All the umbrellas were back.","note":"真实口语常用更简单的说法,但书面/考试要体现完成被动"}]}'::jsonb, 'fltrp');
